begin;
with j as (select * from jsonb_to_recordset($law7d0058$[{"code_id":"NK_RF","article_number":"25.4","version_date":"2000-07-31","article_text":"1. Договор о создании консолидированной группы налогоплательщиков может быть изменен в порядке и на условиях, которые предусмотрены настоящей статьей.\n\n2. Стороны договора о создании консолидированной группы налогоплательщиков обязаны внести изменения в указанный договор в случае:\n\n1) принятия решения о ликвидации одной или нескольких организаций - участников консолидированной группы налогоплательщиков;\n\n2) принятия решения о реорганизации (в форме слияния, присоединения, выделения и разделения) одной или нескольких организаций - участников консолидированной группы налогоплательщиков;\n\n3) присоединения организации к консолидированной группе налогоплательщиков;\n\n4) выхода организации из консолидированной группы налогоплательщиков (в том числе в случаях, когда такая организация перестает удовлетворять условиям, предусмотренным статьей 252 настоящего Кодекса, включая случаи ее слияния с организацией, не являющейся участником указанной группы, разделения (выделения) организации, являющейся участником этой группы);\n\n5) принятия решения о продлении срока действия договора о создании консолидированной группы налогоплательщиков.\n\n3. Соглашение об изменении договора о создании консолидированной группы налогоплательщиков (решение о продлении срока действия указанного договора) принимается всеми участниками такой группы, включая вновь присоединяющихся участников и исключая участников, выходящих из группы.\n\n4. Соглашение об изменении договора о создании консолидированной группы налогоплательщиков (решение о продлении срока действия указанного договора) представляется для регистрации в налоговый орган в следующие сроки:\n\n1) не позднее одного месяца до начала очередного налогового периода по налогу на прибыль организаций - при внесении изменений, связанных с присоединением к группе новых участников (за исключением случаев реорганизации участников указанной группы);\n\n2) не позднее одного месяца до истечения срока действия договора о создании консолидированной группы налогоплательщиков - при принятии решения о продлении срока действия указанного договора;\n\n3) в течение одного месяца со дня возникновения обстоятельств для изменения договора о создании консолидированной группы налогоплательщиков - в прочих случаях.\n\n5. Для регистрации соглашения об изменении договора о создании консолидированной группы налогоплательщиков (решения о продлении срока действия указанного договора) ее ответственный участник представляет в налоговый орган следующие документы:\n\n1) уведомление о внесении изменений в договор;\n\n2) подписанные уполномоченными лицами участников консолидированной группы налогоплательщиков два экземпляра соглашения об изменении договора;\n\n3) документы, подтверждающие полномочия лиц, подписавших соглашение о внесении изменений в договор;\n\n4) документы, подтверждающие выполнение условий, предусмотренных статьей 252 настоящего Кодекса, с учетом внесенных изменений в договор;\n\n5) два экземпляра решения о продлении срока действия договора.\n\n6. Налоговый орган обязан зарегистрировать изменения договора о создании консолидированной группы налогоплательщиков в течение 10 дней со дня представления документов, указанных в пункте 5 настоящей статьи, и выдать уполномоченному представителю ответственного участника указанной группы один экземпляр изменений с отметкой о его регистрации.\n\n7. Основаниями для отказа в регистрации изменений договора о создании консолидированной группы налогоплательщиков являются:\n\n1) невыполнение условий, предусмотренных статьей 252 настоящего Кодекса, в отношении хотя бы одного участника консолидированной группы налогоплательщиков;\n\n2) подписание документов не уполномоченными на это лицами;\n\n3) нарушение срока представления документов на изменение указанного договора;\n\n4) непредставление (представление не в полном объеме) документов, предусмотренных пунктом 5 настоящей статьи.\n\n8. Изменения договора о создании консолидированной группы налогоплательщиков вступают в силу в следующем порядке:\n\n1) изменения договора о создании консолидированной группы налогоплательщиков, связанные с присоединением к такой группе новых организаций (за исключением случаев реорганизации участников группы), вступают в силу не ранее 1-го числа налогового периода по налогу на прибыль организаций, следующего за календарным годом, в котором соответствующие изменения договора зарегистрированы налоговым органом;\n\n2) изменения договора о создании консолидированной группы налогоплательщиков, связанные с выходом участников из состава такой группы, вступают в силу с 1-го числа налогового периода по налогу на прибыль организаций, в котором возникли обстоятельства для внесения соответствующих изменений в договор (если иное не предусмотрено подпунктом 3 настоящего пункта);\n\n3) изменения договора о создании консолидированной группы налогоплательщиков, связанные с выходом участников из состава такой группы, которые на момент регистрации налоговым органом соответствующих изменений договора соответствуют условиям, предусмотренным статьей 252 настоящего Кодекса, вступают в силу с 1-го числа налогового периода по налогу на прибыль организаций, следующего за календарным годом, в котором соответствующие изменения договора зарегистрированы налоговым органом;\n\n4) в прочих случаях изменения договора о создании консолидированной группы налогоплательщиков вступают в силу с даты, указанной его сторонами, но не ранее даты регистрации соответствующих изменений налоговым органом.\n\n9. Уклонение от внесения обязательных изменений в договор о создании консолидированной группы налогоплательщиков влечет прекращение действия договора с 1-го числа налогового периода по налогу на прибыль организаций, в котором соответствующие обязательные изменения договора должны были бы вступить в силу.","article_title":"Статья 25.4. Изменение договора о создании консолидированной группы налогоплательщиков и продление срока его действия","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4b635c03bd04917965629637c40ba44ad855ef1f6b15adacf981b7b15447e93c"},{"code_id":"NK_RF","article_number":"25.5","version_date":"2000-07-31","article_text":"1. Ответственный участник консолидированной группы налогоплательщиков, если иное не предусмотрено настоящим Кодексом, осуществляет права и несет обязанности, предусмотренные настоящим Кодексом для налогоплательщиков налога на прибыль организаций, в отношениях, регулируемых законодательством о налогах и сборах, возникающих в связи с действием консолидированной группы налогоплательщиков.\n\n2. Ответственный участник консолидированной группы налогоплательщиков имеет право:\n\n1) представлять налоговым органам и их должностным лицам любые пояснения по исчислению и уплате налога на прибыль организаций (авансовых платежей) по консолидированной группе налогоплательщиков;\n\n2) присутствовать при проведении выездных налоговых проверок, проводимых в связи с уплатой налога на прибыль организаций по консолидированной группе налогоплательщиков, по месту нахождения любого участника такой группы и его обособленных подразделений;\n\n3) получать копии актов налоговых проверок и решений налогового органа, вынесенных по результатам проверок, проводимых в связи с уплатой налога на прибыль организаций по консолидированной группе налогоплательщиков, а также получать требования об уплате налога на прибыль организаций (авансовых платежей) и иные документы, связанные с действием консолидированной группы налогоплательщиков;\n\n4) участвовать при рассмотрении руководителем (заместителем руководителя) налогового органа материалов налоговых проверок и дополнительных мероприятий налогового контроля, проводимых в связи с уплатой налога на прибыль организаций по консолидированной группе налогоплательщиков, в случаях и порядке, которые предусмотрены статьей 101 настоящего Кодекса;\n\n5) получать от налоговых органов сведения об участниках консолидированной группы налогоплательщиков, составляющие налоговую тайну;\n\n6) обжаловать в установленном порядке акты налоговых органов, иных уполномоченных органов и действия или бездействие их должностных лиц, в том числе в интересах отдельных участников консолидированной группы налогоплательщиков в связи с исполнением ими обязанностей (осуществлением прав) при исчислении налога на прибыль организаций по консолидированной группе налогоплательщиков;\n\n7) обращаться в налоговый орган с заявлением о зачете (возврате) излишне уплаченного налога на прибыль организаций по консолидированной группе налогоплательщиков.\n\n3. Ответственный участник консолидированной группы налогоплательщиков обязан:\n\n1) представлять в порядке и сроки, которые предусмотрены настоящим Кодексом, в налоговый орган для регистрации договор о создании консолидированной группы налогоплательщиков, изменения договора о создании консолидированной группы налогоплательщиков, решение или уведомление о прекращении действия консолидированной группы налогоплательщиков;\n\n2) вести налоговый учет, исчислять и уплачивать налог на прибыль организаций (авансовые платежи) по консолидированной группе налогоплательщиков в порядке, установленном главой 25 настоящего Кодекса;\n\n3) представлять в налоговый орган налоговую декларацию по налогу на прибыль организаций по консолидированной группе налогоплательщиков, а также документы, полученные от других участников этой группы, в порядке и сроки, которые установлены настоящим Кодексом;\n\n4) в случаях прекращения действия консолидированной группы налогоплательщиков и (или) выхода организации из состава консолидированной группы налогоплательщиков представлять другим участникам этой группы (в том числе вышедшим из состава группы или реорганизованным) сведения, необходимые для исчисления и уплаты налога на прибыль организаций (авансовых платежей) и составления налоговых деклараций за соответствующие отчетные и налоговый периоды, в порядке и сроки, которые предусмотрены договором о создании консолидированной группы налогоплательщиков;\n\n5) уплачивать недоимку, пени и штрафы, возникающие в связи с исполнением обязанностей налогоплательщика налога на прибыль организаций по консолидированной группе налогоплательщиков;\n\n6) информировать участников консолидированной группы налогоплательщиков о получении требования об уплате налогов и сборов в течение пяти дней со дня его получения;\n\n7) истребовать у участников консолидированной группы налогоплательщиков документы, пояснения и иную информацию, необходимую для осуществления налоговыми органами мероприятий налогового контроля и исполнения обязанностей налогоплательщика налога на прибыль организаций по консолидированной группе налогоплательщиков;\n\n8) представлять первичные документы, регистры налогового учета и иную информацию по консолидированной группе налогоплательщиков, истребованную в рамках мероприятий налогового контроля налоговым органом, которым зарегистрирован договор о создании указанной группы;\n\n9) представлять в налоговый орган по месту своего учета информацию о прогнозируемых поступлениях от консолидированной группы налогоплательщиков по налогу на прибыль организаций в бюджеты субъектов Российской Федерации в текущем финансовом году, на очередной финансовый год и плановый период и о факторах, оказывающих влияние на планируемые поступления налога на прибыль организаций. Указанная информация представляется по требованию налогового органа в срок не позднее 30 календарных дней со дня получения соответствующего требования. (Дополнение подпунктом - Федеральный закон от 03.08.2018 № 302-ФЗ)\n\n4. Ответственный участник консолидированной группы налогоплательщиков в пределах предоставленных ему полномочий имеет иные права и несет другие обязанности налогоплательщика, предусмотренные настоящим Кодексом.\n\n5. Участники консолидированной группы налогоплательщиков обязаны:\n\n1) представлять (в том числе в электронной форме) ответственному участнику консолидированной группы налогоплательщиков расчеты налоговой базы по налогу на прибыль организаций в отношении полученных ими доходов и расходов, данные регистров налогового учета и иные документы, необходимые ответственному участнику указанной группы для исполнения им обязанностей и осуществления прав налогоплательщика налога на прибыль организаций по консолидированной группе налогоплательщиков; (В редакции Федерального закона от 29.06.2012 № 97-ФЗ)\n\n2) представлять в налоговые органы в установленные настоящим Кодексом сроки и порядке истребуемые документы и иную информацию при осуществлении налоговым органом мероприятий налогового контроля в связи с действием консолидированной группы налогоплательщиков;\n\n3) исполнять обязанность по уплате налога на прибыль организаций (авансовых платежей) по консолидированной группе налогоплательщиков, соответствующих пеней и штрафов в случае неисполнения или ненадлежащего исполнения такой обязанности ответственным участником этой группы в порядке, установленном статьями 45 - 47 настоящего Кодекса;\n\n4) осуществлять все действия и предоставлять все документы, необходимые для регистрации договора о создании консолидированной группы налогоплательщиков и\n\nего изменений;\n\n5) в случае несоблюдения условий, предусмотренных статьей 252 настоящего Кодекса, незамедлительно уведомить ответственного участника консолидированной группы налогоплательщиков и налоговый орган, в котором зарегистрирован договор о создании указанной группы;\n\n6) вести налоговый учет в порядке, предусмотренном главой 25 настоящего Кодекса.\n\n6. В случае неисполнения или ненадлежащего исполнения ответственным участником консолидированной группы налогоплательщиков обязанности по уплате налога на прибыль организаций (авансовых платежей, соответствующих пеней и штрафов) участник (участники) этой группы, исполнивший (исполнившие) указанную обязанность, приобретает (приобретают) право регрессного требования в размерах и порядке, которые предусмотрены гражданским законодательством Российской Федерации и договором о создании указанной группы.\n\n7. Участники консолидированной группы налогоплательщиков вправе:\n\n1) получать от ответственного участника указанной группы копии актов, решений, требований, актов сверки и иных документов, предоставленных ответственному участнику налоговым органом в связи с действием консолидированной группы налогоплательщиков;\n\n2) самостоятельно обжаловать в вышестоящий налоговый орган или в суд акты налоговых органов, действия или бездействие их должностных лиц с учетом особенностей, предусмотренных настоящим Кодексом;\n\n3) добровольно исполнять обязанность ответственного участника консолидированной группы налогоплательщиков по уплате налога на прибыль организаций по консолидированной группе налогоплательщиков;\n\n4) присутствовать при проведении налоговых проверок, проводимых в связи с исчислением и уплатой налога на прибыль организаций по консолидированной группе налогоплательщиков у такого участника, а также участвовать при рассмотрении материалов таких налоговых проверок.\n\n8. Организация при выходе из состава консолидированной группы налогоплательщиков обязана:\n\n1) внести изменения в налоговый учет с начала налогового периода по налогу на прибыль организаций, с 1-го числа которого указанная организация вышла из состава консолидированной группы налогоплательщиков, направленные на соблюдение требований главы 25 настоящего Кодекса по налоговому учету налогоплательщика, не являющегося участником консолидированной группы налогоплательщиков;\n\n2) исчислить и уплатить налог на прибыль организаций (авансовые платежи) исходя из фактически полученной прибыли за соответствующие отчетные и налоговый периоды в сроки, установленные главой 25 настоящего Кодекса применительно к налоговому периоду, с 1-го числа которого организация вышла из состава консолидированной группы налогоплательщиков;\n\n3) по окончании налогового периода, с 1-го числа которого указанная организация вышла из состава консолидированной группы налогоплательщиков, представить в налоговый орган по месту своего учета налоговую декларацию по налогу на прибыль организаций в сроки, предусмотренные главой 25 настоящего Кодекса.\n\n9. Ответственный участник консолидированной группы налогоплательщиков при выходе из состава указанной группы одного или нескольких участников обязан:\n\n1) внести соответствующие изменения в налоговый учет с начала налогового периода по налогу на прибыль организаций, в котором участник (участники) вышел (вышли) из состава консолидированной группы налогоплательщиков;\n\n2) произвести перерасчет авансовых платежей по налогу на прибыль организаций по истекшим отчетным периодам и представить в налоговый орган по месту учета уточненные налоговые декларации по налогу на прибыль организаций по консолидированной группе налогоплательщиков.\n\n10. Выход организации из состава консолидированной группы налогоплательщиков не освобождает ее от исполнения в соответствии со статьями 45 - 47 настоящего Кодекса обязанности по уплате налога на прибыль организаций, соответствующих пеней и штрафов, возникших в период, когда организация являлась участником такой группы.\n\nНастоящее положение применяется независимо от того, было или не было известно указанной организации до ее выхода из состава консолидированной группы налогоплательщиков о неисполнении указанной обязанности или нарушении законодательства Российской Федерации о налогах и сборах либо соответствующие обстоятельства стали известны организации после ее выхода из состава консолидированной группы налогоплательщиков.\n\n11. Пункты 8 - 10 настоящей статьи применяются также в случае прекращения действия консолидированной группы налогоплательщиков до истечения срока, на который она была создана.","article_title":"Статья 25.5. Права и обязанности ответственного участника и других участников консолидированной группы налогоплательщиков","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c1c9ff474a2cfbcfd2467bb786ef9c5c89a15b141e67880725ef4be330e4c896"},{"code_id":"NK_RF","article_number":"25.6","version_date":"2000-07-31","article_text":"1. Консолидированная группа налогоплательщиков прекращает действовать при наличии хотя бы одного из следующих обстоятельств:\n\n1) окончание срока действия договора о создании консолидированной группы налогоплательщиков;\n\n2) расторжение договора о создании консолидированной группы налогоплательщиков по соглашению сторон;\n\n3) вступление в законную силу решения суда о признании договора о создании консолидированной группы налогоплательщиков недействительным;\n\n4) непредставление в налоговый орган в установленные сроки соглашения об изменении договора о создании консолидированной группы налогоплательщиков в связи с выходом из состава указанной группы организации, нарушившей условия, установленные статьей 252 настоящего Кодекса;\n\n5) реорганизация (за исключением реорганизации в форме преобразования), ликвидация ответственного участника консолидированной группы налогоплательщиков;\n\n6) введение в отношении ответственного участника консолидированной группы налогоплательщиков одной из процедур банкротства (за исключением наблюдения), предусмотренных законодательством Российской Федерации о несостоятельности (банкротстве); (В редакции Федерального закона от 30.11.2016 № 401-ФЗ)\n\n7) несоответствие ответственного участника консолидированной группы налогоплательщиков условиям, предусмотренным статьей 252 настоящего Кодекса;\n\n8) уклонение от внесения обязательных изменений в договор о создании консолидированной группы налогоплательщиков.\n\n2. Приобретение (продажа) акций (долей) в уставном (складочном) капитале (фонде) организации - участника консолидированной группы налогоплательщиков, не приводящее к нарушению условий, предусмотренных пунктом 2 статьи 252 настоящего Кодекса, не влечет прекращения действия консолидированной группы налогоплательщиков.\n\n3. При наличии обстоятельства, указанного в подпункте 2 пункта 1 настоящей статьи, ответственный участник консолидированной группы налогоплательщиков обязан направить в налоговый орган, зарегистрировавший договор о создании этой группы, решение о прекращении действия такой группы, подписанное уполномоченными представителями всех организаций - участников консолидированной группы налогоплательщиков, в срок не позднее пяти дней со дня принятия соответствующего решения.\n\nПри наличии обстоятельств, указанных в подпунктах 1, 3 - 7 пункта 1 настоящей статьи, ответственный участник консолидированной группы налогоплательщиков обязан направить в налоговый орган, зарегистрировавший договор о создании этой группы, уведомление, составленное в произвольной форме, с указанием даты возникновения таких обстоятельств.\n\nВ течение пяти дней с даты получения документов, указанных в абзацах первом и втором настоящего пункта, информация о прекращении действия консолидированной группы налогоплательщиков направляется налоговым органом в налоговые органы по месту нахождения организаций - участников консолидированной группы налогоплательщиков, а также по месту нахождения обособленных подразделений организаций - участников консолидированной группы налогоплательщиков.\n\n4. Консолидированная группа налогоплательщиков прекращает действие с 1-го числа налогового периода по налогу на прибыль организаций, следующего за налоговым периодом, в котором возникли обстоятельства, указанные в пункте 1 настоящей статьи, если иное не предусмотрено настоящим Кодексом.\n\n5. При наличии основания, предусмотренного подпунктом 3 пункта 1 настоящей статьи, консолидированная группа налогоплательщиков прекращает действие с 1-го числа отчетного периода по налогу на прибыль организаций, в котором вступило в законную силу решение суда, указанное в подпункте 3 пункта 1 настоящей статьи.\n\n6. При наличии основания, предусмотренного подпунктом 4 пункта 1 настоящей статьи, консолидированная группа налогоплательщиков прекращает действие с 1-го числа налогового периода по налогу на прибыль организаций, в котором участник этой группы нарушил условия, установленные статьей 252 настоящего Кодекса.\n\n(Дополнение главой - Федеральный закон от 30.09.2013 № 268-ФЗ)","article_title":"Статья 25.6. Прекращение действия консолидированной группы налогоплательщиков","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b921b9c77b0d086fde707f032fab66a7d64d5dc584db44a3d0587d544a1b5cd6"},{"code_id":"NK_RF","article_number":"25.7","version_date":"2000-07-31","article_text":"1. В целях настоящего Кодекса организация признается оператором нового морского месторождения углеводородного сырья в случае, если такая организация одновременно удовлетворяет следующим условиям:\n\n1) в уставном капитале организации прямо или косвенно участвует организация, владеющая лицензией на пользование участком недр, в границах которого предполагается осуществлять поиск, оценку, разведку и (или) разработку нового морского месторождения углеводородного сырья, либо организация, являющаяся взаимозависимым лицом с организацией, владеющей такой лицензией;\n\n2) организация осуществляет хотя бы один из видов деятельности, связанной с добычей углеводородного сырья на новом морском месторождении углеводородного сырья, собственными силами и (или) с привлечением подрядных организаций;\n\n3) организация осуществляет деятельность, связанную с добычей углеводородного сырья на новом морском месторождении углеводородного сырья, на основе договора, заключенного с владельцем лицензии в отношении нового морского месторождения углеводородного сырья и (или) участка недр, указанного в подпункте 1 настоящего пункта, и такой договор предусматривает выплату организации-оператору вознаграждения, размер которого зависит в том числе от объема добытого углеводородного сырья на соответствующем морском месторождении углеводородного сырья и (или) выручки от реализации этого сырья (далее в настоящем Кодексе - операторский договор).\n\n2. Организация признается оператором нового морского месторождения углеводородного сырья с даты заключения операторского договора, указанного в подпункте 3 пункта 1 настоящей статьи, если налоговый орган был уведомлен о заключении договора в соответствии с пунктом 3 настоящей статьи.\n\n3. Организация - владелец лицензии на пользование участком недр, указанная в подпункте 3 пункта 1 настоящей статьи, в течение десяти рабочих дней с даты заключения операторского договора уведомляет налоговый орган по месту своего учета о заключении операторского договора путем представления в налоговый орган следующих документов:\n\n1) уведомления о заключении операторского договора с указанием информации о новых морских месторождениях углеводородного сырья (при наличии такой информации на дату представления уведомления);\n\n2) заверенной копии подписанного операторского договора;\n\n3) копии лицензии на пользование участком недр, в границах которого осуществляются поиск, оценка, разведка и (или) разработка новых морских месторождений углеводородного сырья или расположено (расположены) новое морское месторождение (новые морские месторождения) углеводородного сырья.\n\n4. В целях настоящего Кодекса не допускается, чтобы одновременно на одном и том же новом морском месторождении углеводородного сырья осуществляли деятельность, связанную с добычей углеводородного сырья на указанном новом морском месторождении углеводородного сырья, два и более оператора нового морского месторождения углеводородного сырья.\n\nВ случае заключения организацией - владельцем лицензии на пользование участком недр, в границах которого осуществляются поиск, оценка, разведка и (или) разработка нового морского месторождения углеводородного сырья, нового операторского договора с иной организацией, одновременно удовлетворяющей условиям, установленным пунктом 1 настоящей статьи, указанная иная организация получает статус оператора нового морского месторождения углеводородного сырья в целях настоящего Кодекса с даты уведомления налогового органа о заключении операторского договора в соответствии с пунктом 3 настоящей статьи.\n\n5. Для целей настоящего Кодекса организация утрачивает статус оператора нового морского месторождения углеводородного сырья при наступлении наиболее ранней из следующих дат:\n\n1) даты прекращения действия операторского договора, предусмотренной указанным договором;\n\n2) даты истечения срока лицензии на пользование участком недр, в границах которого расположено указанное новое морское месторождение углеводородного сырья, или прекращения права пользования таким участком недр по иным основаниям, предусмотренным законом;\n\n3) даты ликвидации организации - владельца лицензии на пользование участком недр, в границах которого расположено указанное новое морское месторождение углеводородного сырья.\n\n(Дополнение главой - Федеральный закон от 30.09.2013 № 267-ФЗ)","article_title":"Статья 25.7. Оператор нового морского месторождения углеводородного сырья","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6f440652f0aeef172371557725dfe3f13d199c874e33069263153b5763ebaf42"},{"code_id":"NK_RF","article_number":"25.8","version_date":"2000-07-31","article_text":"1) производство товаров в результате реализации такого инвестиционного проекта осуществляется, если иное не предусмотрено настоящей статьей, исключительно на территории одного из следующих субъектов Российской Федерации:\n\nРеспублика Бурятия,\n\nРеспублика Саха (Якутия),\n\nРеспублика Тыва,\n\nАбзац, (Утратил силу - Федеральный закон от 03.08.2018 № 279-ФЗ)\n\nЗабайкальский край,\n\nКамчатский край,\n\nКрасноярский край,\n\nПриморский край,\n\nХабаровский край,\n\nАмурская область,\n\nИркутская область,\n\nМагаданская область,\n\nСахалинская область,\n\nЕврейская автономная область,\n\nЧукотский автономный округ;\n\n(Подпункт в редакции Федерального закона от 04.06.2014 № 139-ФЗ)\n\n11) производство товаров в результате реализации такого инвестиционного проекта осуществляется, если иное не предусмотрено настоящей статьей, исключительно на территории одного из субъектов Российской Федерации, не указанных в подпункте 1 настоящего пункта; (Дополнение подпунктом - Федеральный закон от 23.05.2016 № 144-ФЗ)\n\n2) региональный инвестиционный проект не может быть направлен на следующие цели:\n\nдобыча и (или) переработка нефти, добыча природного газа и (или) газового конденсата, оказание услуг по транспортировке нефти и (или) нефтепродуктов, газа и (или) газового конденсата;\n\nпроизводство подакцизных товаров (за исключением легковых автомобилей, мотоциклов, стали жидкой, этана, сжиженного углеводородного газа, нефтяного сырья, состоящего из одного компонента - газового конденсата стабильного и полученного в рамках единого технологического процесса по производству этана и (или) сжиженного углеводородного газа); (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\nосуществление деятельности, по которой применяется налоговая ставка по налогу на прибыль организаций в размере 0 процентов;\n\n3) (Подпункт утратил силу - Федеральный закон от 23.05.2016 № 144-ФЗ)\n\n4) объем капитальных вложений, определяющих сумму финансирования регионального инвестиционного проекта, в соответствии с инвестиционной декларацией не может быть менее: (В редакции Федерального закона от 29.09.2019 № 325-ФЗ)\n\n50 миллионов рублей при условии осуществления капитальных вложений в срок, не превышающий трех лет со дня включения организации в реестр участников региональных инвестиционных проектов;\n\n500 миллионов рублей при условии осуществления капитальных вложений в срок, не превышающий пяти лет со дня включения организации в реестр участников региональных инвестиционных проектов;\n\n41) объем капитальных вложений, определяющих сумму финансирования регионального инвестиционного проекта и осуществленных российскими организациями, указанными в подпункте 2 пункта 1 статьи 259 настоящего Кодекса, не может быть менее: (В редакции Федерального закона от 29.09.2019 № 325-ФЗ)\n\n50 миллионов рублей при условии осуществления капитальных вложений в срок, не превышающий трех лет со дня начала осуществления капитальных вложений в рамках реализации регионального инвестиционного проекта, но не ранее 1 января 2013 года и не ранее трех лет, предшествующих дате обращения организации в налоговый орган с заявлением о применении налоговой льготы в порядке, предусмотренном пунктами 1 и 2 статьи 2512-1 настоящего Кодекса;\n\n500 миллионов рублей при условии осуществления капитальных вложений в срок, не превышающий пяти лет со дня начала осуществления капитальных вложений в рамках реализации регионального инвестиционного проекта, но не ранее 1 января 2013 года и не ранее пяти лет, предшествующих дате обращения организации в налоговый орган с заявлением о применении налоговой льготы в порядке, предусмотренном пунктами 1 и 2 статьи 2512-1 настоящего Кодекса;\n\n(Дополнение подпунктом - Федеральный закон от 23.05.2016 № 144-ФЗ)\n\n5) каждый региональный инвестиционный проект реализуется единственным участником.\n\n1) региональный инвестиционный проект предусматривает производство товаров участником регионального инвестиционного проекта в рамках единого технологического процесса на территориях нескольких указанных только в подпункте 1 или только в подпункте 11 пункта 1 настоящей статьи субъектов Российской Федерации.\n\nЕдиным технологическим процессом для целей настоящего подпункта признается совокупность взаимосвязанных технологических операций, необходимых для производства товаров при реализации регионального инвестиционного проекта с использованием имущества, указанного в абзаце первом пункта 3 настоящей статьи, расходы на которое\n\nсоставляют объем капитальных вложений, осуществленных участником регионального инвестиционного проекта;\n\n(Подпункт в редакции Федерального закона от 29.09.2019 № 325-ФЗ)\n\n2) региональный инвестиционный проект направлен на добычу полезных ископаемых и соответствующий участок недр частично расположен за пределами территорий указанных только в подпункте 1 или только в подпункте 11 пункта 1 настоящей статьи субъектов Российской Федерации;  (В редакции федеральных законов от 23.05.2016 № 144-ФЗ, от 29.09.2019 № 325-ФЗ)\n\n3) региональный инвестиционный проект, направленный на добычу драгоценных металлов, предусматривает их последующий аффинаж в специализированных организациях, перечень которых установлен в соответствии с Федеральным законом от 26 марта 1998 года № 41-ФЗ \"О драгоценных металлах и драгоценных камнях\". (Дополнение подпунктом - Федеральный закон от 29.09.2019 № 325-ФЗ)\n\nПри этом не учитываются:\n\nполученные участником регионального инвестиционного проекта машины, оборудование, транспортные средства и иное амортизируемое имущество, затраты на которые ранее включались в объем капитальных вложений участниками других региональных инвестиционных проектов;\n\nзатраты, понесенные российскими организациями, указанными в подпункте 1 пункта 1 статьи 259 настоящего Кодекса, на создание (приобретение) зданий, сооружений, расположенных на земельных участках, на которых осуществляется реализация инвестиционного проекта, на дату включения организации в реестр участников региональных инвестиционных проектов, за исключением указанных в пункте 31 настоящей статьи затрат, понесенных участниками региональных инвестиционных проектов, включенных в реестр участников региональных инвестиционных проектов до 1 января 2019 года; (В редакции  федеральных законов от 23.05.2016 № 144-ФЗ, от 31.07.2023 № 389-ФЗ)\n\nзатраты, понесенные российскими организациями, указанными в подпункте 2 пункта 1 статьи 259 настоящего Кодекса, на создание (приобретение) зданий, сооружений, расположенных на земельных участках, на которых осуществляется реализация инвестиционного проекта, на дату начала осуществления капитальных вложений по инвестиционному проекту, произведенные ранее 1 января 2013 года, а также произведенные ранее трех лет, предшествующих дате обращения организации в налоговый орган с заявлением о применении налоговой льготы в порядке, предусмотренном пунктами 1 и 2 статьи 2512-1 настоящего Кодекса, при реализации инвестиционного проекта, удовлетворяющего требованиям, установленным абзацем вторым подпункта 41 пункта 1 настоящей статьи, или ранее пяти лет, предшествующих указанной дате, при реализации инвестиционного проекта, удовлетворяющего требованиям, установленным абзацем третьим подпункта 41 пункта 1 настоящей статьи. (Дополнение абзацем - Федеральный закон от 23.05.2016 № 144-ФЗ)","article_title":"Статья 25.8. Общие положения о региональных инвестиционных проектах","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0779b4d8cdbfd25a79ab9d2612b8e60ecefd08ae090086dd9f5c2320a8a2d831"},{"code_id":"NK_RF","article_number":"25.9","version_date":"2000-07-31","article_text":"1. Налогоплательщиком - участником регионального инвестиционного проекта признается:\n\n1) российская организация, которая получила в порядке, установленном настоящей главой, статус участника регионального инвестиционного проекта и которая непрерывно в течение указанных в пунктах 2 - 5 статьи 2843 настоящего Кодекса налоговых периодов применения налоговых ставок, установленных пунктом 15 статьи 284 настоящего Кодекса, отвечает одновременно следующим требованиям:\n\nгосударственная регистрация юридического лица осуществлена на территории субъекта Российской Федерации, в котором реализуется региональный инвестиционный проект;\n\nорганизация не имеет в своем составе обособленных подразделений, расположенных за пределами территории субъекта (территорий субъектов) Российской Федерации, в котором (которых) реализуется региональный инвестиционный проект;\n\nорганизация не применяет специальных налоговых режимов, предусмотренных частью второй настоящего Кодекса;\n\nорганизация не является участником консолидированной группы налогоплательщиков;\n\nорганизация не является некоммерческой организацией, банком, страховой организацией (страховщиком), негосударственным пенсионным фондом, профессиональным участником рынка ценных бумаг, клиринговой организацией;\n\nорганизация не является резидентом особой экономической зоны любого типа, либо территории опережающего развития, либо свободного порта Владивосток, либо Арктической зоны Российской Федерации; (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\nорганизация ранее не была участником регионального инвестиционного проекта и не является участником (правопреемником участника) иного реализуемого регионального инвестиционного проекта;\n\nорганизация не использует право на освобождение от исполнения обязанностей налогоплательщика налога на прибыль организаций, установленное статьей 2463 настоящего Кодекса; (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\n2) российская организация, которая обратилась в налоговый орган с заявлением о применении налоговой льготы по налогу на прибыль организаций и (или) с заявлением о применении налоговой льготы по налогу на добычу полезных ископаемых в порядке, предусмотренном пунктами 1 и 2 статьи 2512-1 настоящего Кодекса, и которая непрерывно в течение указанных в пункте 2 статьи 2843-1 настоящего Кодекса налоговых периодов применения налоговой ставки, установленной пунктом 15-1 статьи 284 настоящего Кодекса, и (или) в течение налоговых периодов, указанных в пункте 2 статьи 3423-1 настоящего Кодекса, отвечает одновременно следующим требованиям:\n\nместом нахождения организации либо местом нахождения ее обособленного подразделения является территория одного из субъектов Российской Федерации, указанных в подпункте 1 пункта 1 статьи 258 настоящего Кодекса;\n\nорганизация не применяет специальных налоговых режимов, предусмотренных частью второй настоящего Кодекса;\n\nорганизация не является участником консолидированной группы налогоплательщиков;\n\nорганизация не является резидентом особой экономической зоны любого типа, либо территории опережающего развития, либо свободного порта Владивосток, либо Арктической зоны Российской Федерации; (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\nорганизация не является участником (правопреемником участника) иного реализуемого регионального инвестиционного проекта;\n\nорганизация не использует право на освобождение от исполнения обязанностей налогоплательщика налога на прибыль организаций, установленное статьей 2463 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\n1) в соответствии с подпунктом 1 пункта 1 настоящей статьи со дня включения организации в реестр участников региональных инвестиционных проектов в порядке, установленном настоящей главой;\n\n2) в соответствии с подпунктом 2 пункта 1 настоящей статьи начиная с налогового периода, в котором впервые одновременно соблюдены условия, предусмотренные пунктом 2 статьи 2843-1 настоящего Кодекса. При этом включение организации в реестр участников региональных инвестиционных проектов не требуется;\n\n3) (Подпункт утратил силу  - Федеральный закон от 02.08.2019 № 269-ФЗ)\n\n(Статья в редакции Федерального закона от 23.05.2016 № 144-ФЗ)","article_title":"Статья 25.9. Налогоплательщики - участники региональных инвестиционных проектов","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3059ed2208432bf1837c1b47c7d367bc4a5906fe90063f79daa6fe308d306a0e"},{"code_id":"NK_RF","article_number":"26","version_date":"2000-07-31","article_text":"1. Налогоплательщик может участвовать в отношениях, регулируемых законодательством о налогах и сборах через законного или уполномоченного представителя, если иное не предусмотрено настоящим Кодексом.\n\n2. Личное участие налогоплательщика в отношениях, регулируемых законодательством о налогах и сборах, не лишает его права иметь представителя, равно как участие представителя не лишает налогоплательщика права на личное участие в указанных правоотношениях.\n\n3. Полномочия представителя должны быть документально подтверждены в соответствии с настоящим Кодексом и иными федеральными законами.","article_title":"Статья 26. Право на представительство в отношениях, регулируемых законодательством о налогах и сборах","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6e52206fc7159ba708ec9614122551f0d67bfb60645542b3b51ee16048aff2f6"},{"code_id":"NK_RF","article_number":"27","version_date":"2000-07-31","article_text":"Законными представителями налогоплательщика - иностранной организации признаются лица, уполномоченные представлять указанную организацию на основании документов, подтверждающих право таких лиц на указанное представительство в соответствии с законодательством иностранного государства, на территории которого эта иностранная организация зарегистрирована. (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)","article_title":"Статья 27. Законный представитель налогоплательщика","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e6fe972982f109fbc92b4293200a2a44c15510bc8b5cf5a404dd8e31290fc72d"},{"code_id":"NK_RF","article_number":"28","version_date":"2000-07-31","article_text":"Действия (бездействие) законных представителей организации, совершенные в связи с участием этой организации в отношениях, регулируемых законодательством о налогах и сборах, признаются действиями (бездействием) этой организации.","article_title":"Статья 28. Действия (бездействие) законных представителей организации","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"56b9501d8c56cbbc79c22985189b2b34b4eda995879535d976b27455ee6ac7fc"},{"code_id":"NK_RF","article_number":"29","version_date":"2000-07-31","article_text":"Уполномоченный представитель налогоплательщика - индивидуального предпринимателя (физического лица, не являющегося индивидуальным предпринимателем) осуществляет свои полномочия на основании нотариально удостоверенной доверенности, доверенности, приравненной к нотариально удостоверенной в соответствии с гражданским законодательством, или доверенности в форме электронного документа, подписанного электронной подписью доверителя, если иное не предусмотрено абзацем третьим настоящего пункта. (В редакции  федеральных законов от 23.11.2020 № 374-ФЗ, от 31.07.2023 № 389-ФЗ)\n\nУполномоченный представитель, указанный в пункте 51 статьи 23 настоящего Кодекса, осуществляет свои полномочия на основании доверенности в форме электронного документа, подписанного усиленной квалифицированной электронной подписью доверителя. (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nЕсли иное не предусмотрено абзацем третьим настоящего пункта, документы, подтверждающие полномочия уполномоченных представителей, должны быть представлены в налоговый орган лицом лично или через представителя либо направлены в налоговый орган в электронной форме в виде электронных документов или электронных образов документов (документов на бумажном носителе, преобразованных в электронную форму путем сканирования с сохранением их реквизитов), подписанных усиленной квалифицированной подписью доверителя. (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nФорматы документа, подтверждающего полномочия уполномоченного представителя, и заявления об отзыве доверенности, созданной в форме электронного документа, и порядок их направления в налоговый орган по телекоммуникационным каналам связи утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов. (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nв ответственный участник этой группы вправе представлять интересы участников указанной консолидированной группы в следующих правоотношениях:\n\n1) в правоотношениях, связанных с регистрацией в налоговых органах договора о создании консолидированной группы налогоплательщиков, а также изменений указанного договора, решения о продлении срока действия договора и его прекращения;\n\n2) в правоотношениях, связанных с принудительным взысканием с участника консолидированной группы налогоплательщиков недоимки по налогу на прибыль организаций по консолидированной группе налогоплательщиков;\n\n3) в правоотношениях, связанных с привлечением организации к ответственности за налоговые правонарушения, совершенные в связи с участием в консолидированной группе налогоплательщиков;\n\n4) в других случаях, когда по характеру совершаемых налоговым органом действий (бездействия) они непосредственно затрагивают права организации, являющейся участником консолидированной группы налогоплательщиков.\n\n(Дополнение пунктом - Федеральный закон от 16.11.2011 № 321-ФЗ)\n\n(Наименование в редакции федеральных законов от 09.07.1999 № 154-ФЗ; от 30.06.2003 № 86-ФЗ; от 29.06.2004 № 58-ФЗ; от 28.12.2010 № 404-ФЗ)\n\n(Наименование в редакции федеральных законов от 09.07.1999 № 154-ФЗ; от 29.06.2004 № 58-ФЗ)","article_title":"Статья 29. Уполномоченный представитель налогоплательщика","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b15dd1d9692b8b2495b91e66290b51773a00e88e56b9fb39fe235f2f990bb7c3"},{"code_id":"NK_RF","article_number":"3","version_date":"2000-07-31","article_text":"Не допускается устанавливать дифференцированные ставки налогов и сборов, налоговые льготы в зависимости от формы собственности, гражданства физических лиц или места происхождения капитала.\n\nАбзац. (Утратил силу - Федеральный закон от 29.07.2004 № 95-ФЗ)\n\nАбзац. (Утратил силу - Федеральный закон от 29.07.2004 № 95-ФЗ)\n\nНи на кого не может быть возложена обязанность уплачивать налоги и сборы, а также иные взносы и платежи, обладающие установленными настоящим Кодексом признаками налогов или сборов, не предусмотренные настоящим Кодексом либо установленные в ином порядке, чем это определено настоящим Кодексом.","article_title":"Статья 3. Основные начала законодательства о налогах и сборах","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2bc4f1db7def4d2addc7658a6325e8a2904ffa9bd193094290ac39b1fd4fdd72"},{"code_id":"NK_RF","article_number":"31","version_date":"2000-07-31","article_text":"1. Налоговые органы вправе:\n\n1) требовать в соответствии с законодательством о налогах и сборах от налогоплательщика, плательщика сбора или налогового агента документы по формам и (или) форматам в электронной форме, установленным государственными органами и органами местного самоуправления, служащие основаниями для исчисления и уплаты (удержания и перечисления) налогов, сборов, а также документы, подтверждающие правильность исчисления и своевременность уплаты (удержания и перечисления) налогов, сборов; (В редакции федеральных законов от 27.07.2010 № 229-ФЗ; от 29.06.2012 № 97-ФЗ)\n\n2) проводить налоговые проверки в порядке, установленном настоящим Кодексом;\n\n21) контролировать исполнение банками обязанностей, установленных настоящим Кодексом. Порядок контроля за исполнением банками обязанностей, установленных настоящим Кодексом, утверждается федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, по согласованию с Центральным банком Российской Федерации; (Дополнение подпунктом - Федеральный закон от 02.04.2014 № 52-ФЗ)\n\n3) производить выемку документов у налогоплательщика, плательщика сбора или налогового агента при проведении налоговых проверок в случаях, когда есть достаточные основания полагать, что эти документы будут уничтожены, сокрыты, изменены или заменены;\n\n4) вызывать на основании письменного уведомления в налоговые органы налогоплательщиков, плательщиков сборов или налоговых агентов для дачи пояснений в связи с уплатой (удержанием и перечислением) ими налогов и сборов либо в связи с налоговой проверкой, а также в иных случаях, связанных с исполнением ими законодательства о налогах и сборах;\n\n5) приостанавливать операции по счетам налогоплательщика, плательщика сбора или налогового агента в банках и налагать арест на имущество налогоплательщика, плательщика сбора или налогового агента в порядке, предусмотренном настоящим Кодексом;\n\n6) в порядке, предусмотренном статьей 92 настоящего Кодекса, осматривать любые используемые налогоплательщиком для извлечения дохода либо связанные с содержанием объектов налогообложения независимо от места их нахождения производственные, складские, торговые и иные помещения и территории, проводить инвентаризацию принадлежащего налогоплательщику имущества. Порядок проведения инвентаризации имущества налогоплательщика при налоговой проверке утверждается Министерством финансов Российской Федерации;\n\n7) определять суммы налогов, подлежащие уплате налогоплательщиками в бюджетную систему Российской Федерации, расчетным путем на основании имеющейся у них информации о налогоплательщике, а также данных об иных аналогичных налогоплательщиках в случаях отказа налогоплательщика допустить должностных лиц налогового органа к осмотру производственных, складских, торговых и иных помещений и территорий, используемых налогоплательщиком для извлечения дохода либо связанных с содержанием объектов налогообложения, непредставления в течение более двух месяцев налоговому органу необходимых для расчета налогов документов, отсутствия учета доходов и расходов, учета объектов налогообложения, ведения учета с нарушением установленного порядка, приведшего к невозможности исчислить налоги, или непредставления налогоплательщиком - иностранной организацией, не осуществляющей деятельность на территории Российской Федерации через постоянное представительство, налоговой декларации по налогу на имущество организаций; (В редакции Федерального закона от 04.11.2014 № 347-ФЗ)\n\n8) требовать от налогоплательщиков, плательщиков сборов, налоговых агентов, их представителей устранения выявленных нарушений законодательства о налогах и сборах и контролировать выполнение указанных требований;\n\n9) взыскивать задолженность в случаях и порядке, которые установлены настоящим Кодексом; (В редакции  федеральных законов от 17.12.2009 № 318-ФЗ, от 14.07.2022 № 263-ФЗ)\n\n10) требовать от банков документы, подтверждающие факт списания со счетов налогоплательщиков, плательщиков сборов, налоговых агентов и с корреспондентских счетов банков денежных средств, перечисляемых в счет исполнения обязанностей налогоплательщиков, плательщиков сборов, налоговых агентов по уплате налогов, сборов, страховых взносов (в том числе в качестве единого налогового платежа), и перечисления этих денежных средств в бюджетную систему Российской Федерации; (В редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\n11) привлекать для проведения налогового контроля специалистов, экспертов и переводчиков;\n\n12) вызывать в качестве свидетелей лиц, которым могут быть известны какие-либо обстоятельства, имеющие значение для проведения налогового контроля;\n\n13) заявлять ходатайства об аннулировании или о приостановлении действия выданных юридическим и физическим лицам лицензий на право осуществления определенных видов деятельности;\n\n14) предъявлять в суды общей юрисдикции, Верховный Суд Российской Федерации или арбитражные суды иски (заявления): (В редакции Федерального закона от 28.06.2014 № 198-ФЗ)\n\nо взыскании задолженности в случаях, предусмотренных настоящим Кодексом; (В редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\nо возмещении ущерба, причиненного государству, муниципальному образованию и (или) федеральной территории \"Сириус\" вследствие неправомерных действий банка по списанию денежных средств (драгоценных металлов) со счета налогоплательщика, операции по которому приостановлены налоговым органом, в результате которых стало невозможным взыскание налоговым органом задолженности с налогоплательщика в порядке, предусмотренном настоящим Кодексом; (В редакции  федеральных законов от 27.11.2017 № 343-ФЗ, от 11.06.2021 № 199-ФЗ, от 14.07.2022 № 263-ФЗ)\n\nо досрочном расторжении договора об инвестиционном налоговом кредите;\n\nв иных случаях, предусмотренных настоящим Кодексом;\n\n15) восстанавливать в случае, предусмотренном пунктом 11 статьи 59 настоящего Кодекса, суммы задолженности, признанной безнадежной к взысканию. (Дополнение подпунктом - Федеральный закон от 03.07.2016 № 244-ФЗ) (В редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\n2. Налоговые органы осуществляют также другие права, предусмотренные настоящим Кодексом.\n\n3. Вышестоящие налоговые органы вправе отменять и изменять решения нижестоящих налоговых органов в случае несоответствия указанных решений законодательству о налогах и сборах.\n\nДокументы, используемые налоговыми органами при реализации своих полномочий в отношениях, регулируемых законодательством о налогах и сборах, могут быть переданы налоговым органом лицу, которому они адресованы, или его представителю непосредственно под расписку, через многофункциональный центр предоставления государственных и муниципальных услуг, направлены по почте заказным письмом или переданы в электронной форме по телекоммуникационным каналам связи через оператора электронного документооборота, либо через личный кабинет налогоплательщика, либо через информационные системы организации, к которым предоставлен доступ налоговому органу, если порядок их передачи прямо не предусмотрен настоящим Кодексом, а также могут быть переданы в электронной форме через личный кабинет на едином портале государственных и муниципальных услуг в соответствии с настоящим Кодексом. Лицам, на которых настоящим Кодексом возложена обязанность представлять налоговую декларацию (расчет) в электронной форме, указанные документы направляются налоговым органом в электронной форме по телекоммуникационным каналам связи через оператора электронного документооборота, либо через личный кабинет налогоплательщика, либо через информационные системы организации, к которым предоставлен доступ налоговому органу. (В редакции  федеральных законов от 04.11.2014 № 347-ФЗ, от 02.05.2015 № 113-ФЗ, от 29.09.2019 № 325-ФЗ, от 29.12.2020 № 470-ФЗ, от 14.04.2023 № 125-ФЗ)\n\nВ случаях направления документа налоговым органом по почте заказным письмом датой его получения считается шестой день со дня отправки заказного письма.\n\nВ случае направления документа налоговым органом через личный кабинет налогоплательщика датой его получения считается день, следующий за днем размещения документа в личном кабинете налогоплательщика. (Дополнение абзацем - Федеральный закон от 02.05.2015 № 113-ФЗ)\n\nДокумент в электронной форме, подписанный автоматически созданной электронной подписью налогового органа, признается равнозначным документу на бумажном носителе, подписанному собственноручной подписью должностного лица налогового органа. (Дополнение абзацем - Федеральный закон от 04.11.2014 № 347-ФЗ)\n\nВ случае направления документа налоговым органом через многофункциональный центр предоставления государственных и муниципальных услуг датой его получения считается день, следующий за днем получения указанного документа многофункциональным центром предоставления государственных и муниципальных услуг, если иное не предусмотрено настоящим Кодексом. (Дополнение абзацем - Федеральный закон от 29.09.2019 № 325-ФЗ)\n\nВ случае направления документа налоговым органом в электронной форме через личный кабинет на едином портале государственных и муниципальных услуг датой его получения считается день, следующий за днем направления документа налоговым органом в электронной форме через личный кабинет на едином портале государственных и муниципальных услуг. (Дополнение абзацем - Федеральный закон от 14.04.2023 № 125-ФЗ)\n\nВ случае направления налоговым органом налогоплательщику, указанному в абзаце первом пункта 51 статьи 23 настоящего Кодекса, документа в электронной форме по телекоммуникационным каналам связи через оператора электронного документооборота датой его получения считается шестой день со дня направления такого документа, указанного в подтверждении даты отправки электронного документа. Подтверждение даты отправки электронного документа направляется оператором электронного документооборота в налоговый орган не позднее дня, следующего за днем направления документа налогоплательщику. (Дополнение абзацем - Федеральный закон от 08.08.2024 № 259-ФЗ)\n\nДокументы (сведения), не содержащие налоговую тайну, используемые налоговыми органами при реализации своих полномочий в отношениях, регулируемых законодательством о налогах и сборах, передаются налоговым органом налогоплательщику - физическому лицу, зарегистрированному в единой системе идентификации и аутентификации, в электронной форме через личный кабинет на едином портале государственных и муниципальных услуг, если такой порядок передачи документов (сведений), не содержащих налоговую тайну, предусмотрен настоящим Кодексом или если указанные документы (сведения) включены в перечень, утверждаемый в соответствии с абзацем первым пункта 9 настоящей статьи. (Дополнение абзацем - Федеральный закон от 31.07.2025 № 287-ФЗ)\n\nДокументы (сведения), не содержащие налоговую тайну, используемые налоговыми органами при реализации своих полномочий в отношениях, регулируемых законодательством о налогах и сборах, налогоплательщикам - физическим лицам, зарегистрированным в единой системе идентификации и аутентификации, направленные через личный кабинет на едином портале государственных и муниципальных услуг, на бумажном носителе по почте не направляются, если иное не предусмотрено пунктом 2 статьи 112 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 31.07.2025 № 287-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 30.12.2006 № 268-ФЗ) (В редакции Федерального закона от 23.07.2013 № 248-ФЗ)\n\nналогоплательщику - российской организации (ее филиалу, представительству) - по адресу места ее нахождения (места нахождения ее филиала, представительства), содержащемуся в Едином государственном реестре юридических лиц;\n\nналогоплательщику - иностранной организации - по адресу места осуществления им деятельности на территории Российской Федерации, содержащемуся в Едином государственном реестре налогоплательщиков;\n\nналогоплательщику - иностранной организации (за исключением международной организации, дипломатического представительства), не осуществляющей деятельность на территории Российской Федерации через обособленное подразделение, - по предоставленному налоговому органу адресу для направления документов, указанных в настоящем пункте, содержащемуся в Едином государственном реестре налогоплательщиков; (Дополнение абзацем - Федеральный закон от 24.11.2014 № 376-ФЗ)\n\nналогоплательщику - иностранной организации, не осуществляющей деятельность на территории Российской Федерации через постоянное представительство и имеющей на территории Российской Федерации объект недвижимого имущества на праве собственности, - по адресу места нахождения указанного объекта недвижимого имущества или по предоставленному налоговому органу адресу; (Дополнение абзацем - Федеральный закон от 04.11.2014 № 347-ФЗ)\n\nналогоплательщику - индивидуальному предпринимателю, нотариусу, занимающемуся частной практикой, адвокату, учредившему адвокатский кабинет, физическому лицу, не являющемуся индивидуальным предпринимателем, - по адресу места его жительства (места пребывания) или по предоставленному налоговому органу адресу для направления документов, указанных в настоящем пункте, содержащемуся в Едином государственном реестре налогоплательщиков. При отсутствии у физического лица, не являющегося индивидуальным предпринимателем, места жительства (места пребывания) на территории Российской Федерации и отсутствии в Едином государственном реестре налогоплательщиков сведений об адресе для направления этому лицу документов, указанных в настоящем пункте, такие документы направляются налоговым органом по адресу места нахождения одного из принадлежащих такому физическому лицу объектов недвижимого имущества (за исключением земельного участка). (В редакции Федерального закона от 29.07.2018 № 232-ФЗ)\n\nФорма заявления о предоставлении налоговому органу адреса для направления по почте документов, которые используются налоговыми органами при реализации своих полномочий в отношениях, регулируемых законодательством о налогах и сборах, утверждается федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов. (В редакции Федерального закона о\n\n(Дополнение пунктом - Федеральный закон от 28.06.2013 № 134-ФЗ)\n\nДо предоставления иностранному лицу, подлежащему постановке на учет в налоговом органе в соответствии с пунктом 46 статьи 83 настоящего Кодекса, доступа к личному кабинету налогоплательщика в соответствии с абзацем вторым пункта 3 статьи 112 настоящего Кодекса документы, которые используются налоговыми органами при реализации своих полномочий в отношениях, регулируемых законодательством о налогах и сборах, передаются по любому известному налоговому органу адресу электронной почты такого иностранного лица. В этом случае датой получения иностранным лицом соответствующего документа считается день, следующий за днем его передачи по адресу электронной почты. (В редакции  Федерального закона от 29.05.2024 № 100-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 03.07.2016 № 244-ФЗ)\n\nДокументы (сведения), представляемые в налоговый орган через многофункциональный центр предоставления государственных и муниципальных услуг, не позднее дня, следующего за днем их приема, направляются многофункциональным центром предоставления государственных и муниципальных услуг в налоговый орган в форме электронных документов, если иное не предусмотрено настоящим пунктом.\n\nПорядок взаимодействия налоговых органов с многофункциональными центрами предоставления государственных и муниципальных услуг в электронной форме и требования к формированию электронных документов, используемых при таком взаимодействии, утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\nПорядок передачи документов (сведений), принятых многофункциональными центрами предоставления государственных и муниципальных услуг, в налоговые органы на бумажном носителе, порядок передачи по результатам рассмотрения указанных документов (сведений) налоговыми органами документов на бумажном носителе через многофункциональные центры предоставления государственных и муниципальных услуг определяются соглашением взаимодействующих сторон.\n\nВ случае представления физическим лицом в налоговый орган документов (сведений), за исключением налоговых деклараций, через многофункциональный центр предоставления государственных и муниципальных услуг по просьбе этого физического лица, выраженной в письменной форме, о получении по результатам рассмотрения указанных документов (сведений) от налогового органа документа через многофункциональный центр предоставления государственных и муниципальных услуг налоговый орган обязан в срок, не превышающий двух дней после подготовки соответствующего документа, передать такой документ в многофункциональный центр предоставления государственных и муниципальных услуг для его получения физическим лицом на бумажном носителе.\n\nПередача налоговым органом физическому лицу документов, содержащих сведения о нем, составляющие налоговую тайну, на бумажном носителе через многофункциональный центр предоставления государственных и муниципальных услуг осуществляется при наличии письменного согласия на это указанного физического лица, которое может быть выражено им в документе (сведениях), представляемых в налоговый орган через многофункциональный центр предоставления государственных и муниципальных услуг.\n\n(Дополнение пунктом - Федеральный закон от 29.09.2019 № 325-ФЗ)\n\nПередача налоговым органом налогоплательщику - физическому лицу документов, содержащих сведения о нем, составляющие налоговую тайну, в электронной форме через личный кабинет на едином портале государственных и муниципальных услуг осуществляется при наличии согласия на это указанного налогоплательщика, выраженного им в уведомлении о необходимости получения документов с использованием единого портала государственных и муниципальных услуг.\n\n(Дополнение пунктом - Федеральный закон от 14.04.2023 № 125-ФЗ) (В редакции  Федерального закона от 31.07.2025 № 287-ФЗ)\n\n(Статья в редакции Федерального закона от 27.07.2006 № 137-ФЗ)","article_title":"Статья 31. Права налоговых органов","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"50b17d230235e1e9d13cb3da3c010e4949edcdc14e60bdafaa143d2bd0711c05"}]$law7d0058$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text))
insert into law7_mirror.article_versions(code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,source_commit,imported_at)
